<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { Cpu, Plus, ShieldCheck, Trash2, Pencil, PlugZap, ToggleLeft, ToggleRight, ChevronDown } from 'lucide-vue-next'
import PageHeader from '../components/PageHeader.vue'; import EmptyState from '../components/EmptyState.vue'; import AppDialog from '../components/AppDialog.vue'
import { useResourcesStore } from '../stores/resources'; import { useAppStore } from '../stores/app'; import { api } from '../api/client'; import type { Provider, ProviderTest } from '../types/api'
const store = useResourcesStore(); const app = useAppStore(); const editorOpen = ref(false); const editing = ref<Provider | null>(null); const deleteTarget = ref<Provider | null>(null); const testing = ref<number | null>(null); const testResults = ref<Record<number, ProviderTest>>({}); const advanced = ref(false); const form = ref({ name:'', base_url:'', model:'', secret_reference:'', enabled:true, temperature:null as number|null, max_tokens:null as number|null, max_context_tokens:null as number|null, timeout_s:30 })
onMounted(() => store.loadProviders())
function reset() { form.value = { name:'', base_url:'', model:'', secret_reference:'', enabled:true, temperature:null, max_tokens:null, max_context_tokens:null, timeout_s:30 } }
function openCreate() { editing.value = null; reset(); editorOpen.value = true }; function openEdit(provider: Provider) { editing.value = provider; form.value = { name:provider.name, base_url:provider.base_url, model:provider.model, secret_reference:provider.secret_reference || '', enabled:provider.enabled, temperature:provider.temperature, max_tokens:provider.max_tokens, max_context_tokens:provider.max_context_tokens, timeout_s:provider.timeout_s }; editorOpen.value = true }
async function save() { try { const body = { ...form.value, provider_type:'openai_compatible', secret_reference:form.value.secret_reference || null }; const saved = editing.value ? await api.updateProvider(editing.value.id, body) : await api.createProvider(body); if (editing.value) Object.assign(editing.value, saved); else store.providers.push(saved); editorOpen.value = false; app.toast('提供商已保存') } catch (e) { app.toast(e instanceof Error ? e.message : '保存失败') } }
async function toggle(provider: Provider) { try { Object.assign(provider, await api.updateProvider(provider.id, { enabled:!provider.enabled })); app.toast(provider.enabled ? '已启用提供商' : '已停用提供商') } catch (e) { app.toast(e instanceof Error ? e.message : '更新失败') } }
async function test(provider: Provider) { testing.value = provider.id; try { testResults.value[provider.id] = await api.testProvider(provider.id) } catch (e) { testResults.value[provider.id] = { ok:false, latency_ms:null, error_category:'request', message:e instanceof Error ? e.message : '测试失败' } } finally { testing.value = null } }
async function remove() { if (!deleteTarget.value) return; try { await api.deleteProvider(deleteTarget.value.id); store.providers = store.providers.filter(p => p.id !== deleteTarget.value?.id); app.toast('提供商已删除'); deleteTarget.value = null } catch (e) { app.toast(e instanceof Error ? e.message : '删除失败') } }
</script>
<template><section class="page-content"><PageHeader eyebrow="AI 配置" title="模型提供商" description="为 AI 助手选择可用的模型连接。密钥只通过后端 secret_reference 管理。"><button class="button button-primary" @click="openCreate"><Plus :size="16" />添加提供商</button></PageHeader><section class="provider-list" v-if="store.providers.length"><article v-for="provider in store.providers" :key="provider.id" class="panel provider-card"><div class="provider-icon"><Cpu :size="19" /></div><div class="provider-body"><div class="provider-title"><h3>{{ provider.name }}</h3><span class="status-badge" :class="provider.enabled ? 'success' : 'muted'">{{ provider.enabled ? '可用' : '已停用' }}</span></div><p>{{ provider.model }}</p><small>{{ provider.base_url }}</small><span v-if="testResults[provider.id]" class="provider-test" :class="{ bad: !testResults[provider.id].ok }">{{ testResults[provider.id].ok ? `连接通过 · ${testResults[provider.id].latency_ms?.toFixed(0) || '—'} ms` : testResults[provider.id].message }}</span></div><div class="provider-safe"><ShieldCheck :size="15" />密钥由后端托管</div><div class="provider-actions"><button class="button button-secondary" :disabled="testing === provider.id" @click="test(provider)"><PlugZap :size="15" />{{ testing === provider.id ? '测试中…' : '测试' }}</button><button class="icon-button" :aria-label="`编辑${provider.name}`" @click="openEdit(provider)"><Pencil :size="17" /></button><button class="icon-button" :aria-label="provider.enabled ? '停用提供商' : '启用提供商'" @click="toggle(provider)"><component :is="provider.enabled ? ToggleRight : ToggleLeft" :size="18" /></button><button class="icon-button danger-button" :aria-label="`删除${provider.name}`" @click="deleteTarget = provider"><Trash2 :size="17" /></button></div></article></section><section v-else class="panel"><EmptyState title="还没有模型提供商" description="添加后，AI 助手才会有可用的模型后端。" /></section><AppDialog :open="editorOpen" :title="editing ? '编辑模型提供商' : '添加模型提供商'" description="只保存 secret_reference，不接触真实密钥" @close="editorOpen = false"><form class="task-editor" @submit.prevent="save"><label>名称<input v-model="form.name" required /></label><label>模型<input v-model="form.model" required /></label><label>Base URL<input v-model="form.base_url" type="url" required placeholder="https://api.example.com/v1" /></label><label>Secret reference<input v-model="form.secret_reference" placeholder="env:YOUR_API_KEY" /></label><button type="button" class="collapse-button" :aria-expanded="advanced" @click="advanced = !advanced"><ChevronDown :size="16" />高级参数</button><div v-if="advanced" class="form-grid"><label>Temperature<input v-model.number="form.temperature" type="number" step="0.1" min="0" /></label><label>Max tokens<input v-model.number="form.max_tokens" type="number" min="1" /></label><label>Max context tokens<input v-model.number="form.max_context_tokens" type="number" min="1" /></label><label>Timeout (s)<input v-model.number="form.timeout_s" type="number" min="1" /></label></div><label class="check-line"><input v-model="form.enabled" type="checkbox" />启用提供商</label><div class="form-actions"><button type="button" class="button button-secondary" @click="editorOpen = false">取消</button><button class="button button-primary">保存提供商</button></div></form></AppDialog><AppDialog :open="Boolean(deleteTarget)" title="删除提供商" @close="deleteTarget = null"><p class="dialog-copy">确定删除“{{ deleteTarget?.name }}”吗？</p><template #footer><button class="button button-secondary" @click="deleteTarget = null">取消</button><button class="button button-danger" @click="remove">删除</button></template></AppDialog></section></template>
